**Context:**
- Playwright Version: 1.23.3
- Operating System: macOS Monterey
- Node.js version: 16.15.0
- Browser: any
- Extra: M1 chip

<!-- CLI to auto-capture this info -->
<!-- npx envinfo --preset playwright --markdown -->

**Code Snippet**

```typescript
//fixture
import { test as base } from '@playwright/test';
import { SearchPage } from '../pages/Search&Apply';
import { SearchFilters } from '../pages/components/SearchFilters';

type SearchFixtures = {
  filters: SearchFilters
}

export const test = base.extend<SearchFixtures>({
  filters: async ({browser, isMobile}, use) => {
    const context = await browser.newContext();
    const page = await context.newPage();
    const search = new SearchPage(page)
    await search.open()
    isMobile ?
      await search.cookiesPopup.closeBtn.tap() :
      await search.cookiesPopup.closeBtn.click()
    await use(search.filters)
  }
})

export const expect = test.expect;
```

```typescript
//test
import { expect } from '@playwright/test';
import { test } from '../../framework/fixtures'
import { SearchFilters } from '../../framework/pages/components/SearchFilters';

test.describe.parallel('Search filters overlay', () => {
  
  test.describe.serial('Area of work', () => {
    let searchFilters: SearchFilters
    
    test.beforeAll(async ({filters}) => {
      searchFilters = filters;
    })

    test.afterAll(async () => {
      searchFilters.page.close()
    })

    test('@smoke: Filters overlay can be opened', async ({isMobile}) => {
      await test.step('Open Area of Work filters', async () => {
        isMobile ?
          await searchFilters.areaOfWorkFilterBtn.tap() :
          await searchFilters.areaOfWorkFilterBtn.click() 
      });
      await test.step('Verify filters overlay and its elements are shown',async () => {
        await expect(searchFilters.filtersHeaderText).toHaveText('Filter by Area of Work')
        await expect(searchFilters.clearAllfiltersBtn).toBeVisible()
        await expect(searchFilters.applyFiltersBtn).toBeVisible()
        await expect(searchFilters.closeFiltersOverlayBtn).toBeVisible()
        expect(await searchFilters.filterCheckboxes.count(), 'expect there are some filters').toBeGreaterThan(0)
      })
    })

    test('@smoke: Filters overlay can be closed', async ({isMobile}) => {
      await test.step('Close Area of Work filters', async () => {
        isMobile ?
          await searchFilters.closeFiltersOverlayBtn.tap() :
          await searchFilters.closeFiltersOverlayBtn.click() 
      })
      await test.step('Verify filters overlay and its elements are shown',async () => {
        await expect(searchFilters.filtersHeaderText).not.toBeVisible()
        await expect(searchFilters.clearAllfiltersBtn).not.toBeVisible()
        await expect(searchFilters.applyFiltersBtn).not.toBeVisible()
        await expect(searchFilters.closeFiltersOverlayBtn).not.toBeVisible()
        expect(await searchFilters.filterCheckboxes.count(), 'expect there are some filters').toBeFalsy()
      })
    })
  })

  test.describe.serial('Location', () => {
    let searchFilters: SearchFilters
    
    test.beforeAll(async ({filters}) => {
      searchFilters = filters;
    })

    test.afterAll(async () => {
      searchFilters.page.close()
    })

    test('@smoke: Filters overlay can be opened', async ({isMobile}) => {
      await test.step('Open Location filters', async () => {
        isMobile ?
          await searchFilters.locationFilterBtn.tap() :
          await searchFilters.locationFilterBtn.click() 
      });
      await test.step('Verify filters overlay and its elements are shown', async () => {
        await expect(searchFilters.filtersHeaderText).toHaveText('Filter by Location')
        await expect(searchFilters.clearAllfiltersBtn).toBeVisible()
        await expect(searchFilters.applyFiltersBtn).toBeVisible()
        await expect(searchFilters.closeFiltersOverlayBtn).toBeVisible()
        expect(await searchFilters.filterCheckboxes.count(), 'expect there are some filters').toBeGreaterThan(0)
      })
    })

    test('@smoke: Filters overlay can be closed', async ({isMobile}) => {
      await test.step('Close Location filters', async () => {
        isMobile ?
          await searchFilters.closeFiltersOverlayBtn.tap() :
          await searchFilters.closeFiltersOverlayBtn.click() 
      })
      await test.step('Verify filters overlay and its elements are shown', async () => {
        await expect(searchFilters.filtersHeaderText).not.toBeVisible()
        await expect(searchFilters.clearAllfiltersBtn).not.toBeVisible()
        await expect(searchFilters.applyFiltersBtn).not.toBeVisible()
        await expect(searchFilters.closeFiltersOverlayBtn).not.toBeVisible()
        expect(await searchFilters.filterCheckboxes.count(), 'expect there are some filters').toBeFalsy()
      })
    })
  })

})
```

**Description**
With the recent change in 1.23 (https://github.com/microsoft/playwright/pull/14530) I tried a parallel run of two `test.describe.serial()`'s  that are located in the single file. The test didn't errored out like in the previous versions, but it didn't utilise two workers. Instead, the test suites ran sequentially.
![2022-07-16_23-46-07](https://user-images.githubusercontent.com/31986966/179371456-35fb25fc-9159-4935-8b91-52fef973e7a3.png)


### **Question**: Is there a way two run those serial test describes in parallel without splitting them into separate files?
